WITH "m0" AS ( INSERT INTO "public"."mutation_item" AS "s" ( "id" , "title" , "score" ) VALUES ( $1 , $2 , $3 ) ON CONFLICT ON CONSTRAINT "mutation_item_pkey" DO NOTHING RETURNING "s" AS "t0" , NULL::tid AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "r0" AS "b0" WHERE true AND "s"."id" = "b0"."id" ) UNION ALL SELECT * FROM "r0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" , "t0"."score" AS "score" , "t0"."note" AS "note" ) AS "%")) FROM "r0" AS "t0" )
